 () {\n            var wrapper = $(this).closest(\'.gform_wrapper\');\n            var formId = (wrapper.attr(\'id\') || \'\').replace(\'gform_wrapper_\', \'\');\n            if (formId && !gfTrackedForms[\'conf_\' + formId]) {\n                gfTrackedForms[\'conf_\' + formId] = true;\n                pushEvent(\'gravity_forms\', formId, null);\n            }\n        });\n\n        // (c) Redirect confirmation — capture before the browser navigates away\n        if (typeof gform !== \'undefined\' && typeof gform.addAction === \'function\') {\n            gform.addAction(\'gform_pre_submission\', function (formEl) {\n                var formId = formEl ? formEl.getAttribute(\'id\') : \'\';\n                formId = formId.replace(\'gform_\', \'\');\n                if (formId) {\n                    pushEvent(\'gravity_forms\', formId, formEl);\n                    gfTrackedForms[\'conf_\' + formId] = true;\n                }\n            });\n        }\n\n        // ── 3. WPForms ─────────────────────────────────────────\n\n        $(document).on(\'wpformsAjaxSubmitSuccess\', \'form.wpforms-form\', function (event) {\n            var formId = $(event.target).attr(\'data-formid\');\n            pushEvent(\'wpforms\', formId, event.target);\n        });\n\n        // ── 4. Forminator ──────────────────────────────────────\n\n        $(document).on(\'forminator:form:submit:success\', function (event) {\n            var formId = $(event.target).find(\'input[name=\"form_id\"]\').val();\n            pushEvent(\'forminator\', formId, event.target);\n        });\n\n        // ── 5. Formidable Forms ────────────────────────────────\n        //   a) AJAX → frmFormComplete fires\n        //   b) Non-AJAX page reload → .frm_message present on load\n\n        var frmTrackedForms = {};\n\n        $(document).on(\'frmFormComplete\', function (event, form) {\n            var formId = $(form).find(\'input[name=\"form_id\"]\').val();\n            if (formId) frmTrackedForms[\'frm_