Observer(function (mutations) {\n                for (var i = 0; i < mutations.length; i++) {\n                    if (form.querySelector(\'.elementor-message-success\')) {\n                        var formId = form.getAttribute(\'id\') ||\n                            (form.querySelector(\'input[name=\"form_id\"]\') || {}).value || \'\';\n                        pushEvent(\'elementor_form\', formId, form);\n                        observer.disconnect();\n                        return;\n                    }\n                }\n            });\n\n            observer.observe(form, {\n                attributes: true,\n                childList:  true,\n                subtree:    true\n            });\n        }\n\n        // existing forms on page\n        document.querySelectorAll(\'.elementor-form\').forEach(function (form) {\n            observeElementorForm(form);\n        });\n\n        // forms inside Elementor popups (loaded dynamically)\n        var popupObserver = new MutationObserver(function (mutationsList) {\n            for (var i = 0; i < mutationsList.length; i++) {\n                var popupForm = document.querySelector(\'[class*=\"elementor-popup\"] form\');\n                if (popupForm) {\n                    observeElementorForm(popupForm);\n                    popupObserver.disconnect();\n                    break;\n                }\n            }\n        });\n        popupObserver.observe(document.body, { childList: true, subtree: true });\n\n        // ── 10. Enfold (Avia) Contact Forms ───────────────────────\n        //\n        // Enfold forms submit via AJAX and do not fire custom JS events.\n        // On success the form slides up and the response container\n        // (#ajaxresponse_{id}) becomes visible with an .avia-form-success heading.\n        // We use a MutationObserver to detect this DOM change.\n\n        var enfoldTracked = {};\n\n        function observeEnfoldResponse(responseEl) {\n            var observer = new MutationObserver(function () {\n                if (responseEl.classList.contains(\'hidden\') ||\n                    responseEl.style.display === \'none\') {\n                    return;\n                }\n\n                if (!responseEl.querySelector(\'.avia-form-success\')) {\n                    return;\n                }\n\n                var formId = (responseEl.id || \'\').replace(\'ajaxresponse_\', \'\');\n                if (enfoldTracked[formId]) return;\n                enfoldTracked[formId] = true;\n\n                var formEl = responseEl.parentElement\n                    ? responseEl.parentElement.querySelector(\'form.avia_ajax_form\') ||\n                    responseEl.parentElement.querySelector(\'form.ajax_form\')\n                    : null;\n\n                pushEvent(\'enfold\', formId, formEl);\n                observer.disconnect();\n            });\n\n            observer.observe(responseEl, {\n                attributes:      true,\n                attributeFilter: [\'class\', \'style\'],\n                childList:       true,\n                subtree:         true\n            });\n        }\n\n        document.querySelectorAll(\'.ajaxresponse\').forEach(function (el) {\n            observeEnfoldResponse(el);\n        });\n\n    });\n\n    // ── 11. HubSpot Forms v3 ───────────────────────────────────\n    //\n    // v3 forms communicate via window.postMessage. On success the\n    // message payload carries the form ID, conversion ID, and field values.\n\n    window.addEventListener(\'message\', function (event) {\n        if (event.data.type === \'hsFormCallback\' &&\n            event.data.eventName === \'onFormSubmitted\') {\n\n            pushEvent(\n                \'hubspot_v3\',\n                event.data.id,\n                null,\n                {\n                    conversion_id: event.data.data.conversionId\n                }\n            );\n        }\n    });\n\n    // ── 12. HubSpot Forms v4 ───────────────────────────────────\n    //\n    // v4 forms fire a custom DOM event. Field values are fetched\n    // asynchronously via the HubspotFormsV4 API.\n\n    window.addEventListener(\'hs-form-event:on-submission:success\', function (event) {\n        if (typeof HubspotFormsV4 === \'undefined\') return;\n\n        var hsForm = HubspotFormsV4.getFormFromEvent(event);\n        if (!hsForm) return;\n\n        pushEvent(\n            \'hubspot_v4\',\n            hsForm.getFormId(),\n            null,\n            {\n                conversion_id: hsForm.getConversionId()\n            }\n        );\n    });\n\n    // ── 13. Lead form submissions ─────────────────────────────\n    //\n    // Lead forms dispatch a custom \'wpseoai:lead_form_submit\' event on\n    // successful submission. The event detail may carry formId and any\n    // additional metadata the form wishes to surface.\n\n    document.addEventListener(\'wpseoai:lead_form_submit\', function (event) {\n        pushEvent(\'wpseoai_lead_form\', \'\', null);\n    }, false);\n\n    // ── 14. Pipedrive LeadBooster Forms ──────────────────────────\n    //\n    // Pipedrive forms are embedded as iframes and post a message to the\n    // parent window on submission. The payload includes formUUID which\n    // serves as the form identifier.\n\n    window.addEventListener(\'message\', function (event) {\n        var data = event.data;\n        if (!data || data.event !== \'pipedrive_form_submit\') return;\n\n        pushEvent(\'pipedrive\', data.formUUID || \'\', null, null);\n    });\n\n    // ── 15. Leadoo ────────────────────────────────────────────────\n    //\n    // Leadoo pushes a { event: \'LEAD\' } object to window.dataLayer on\n    // form submission. We wrap dataLayer.push to intercept it.\n    // The _busy guard prevents re-entrancy from our own pushEvent calls.\n\n    (function () {\n        var dl = window.dataLayer;\n        if (!dl || typeof dl.push !== \'function\') return;\n\n        var _orig = dl.push.bind(dl);\n        var _busy = false;\n\n        dl.push = function () {\n            if (!_busy) {\n                for (var i = 0; i < arguments.length; i++) {\n                    var item = arguments[i];\n                    if (item && typeof item === \'object\' && item.event === \'LEAD\') {\n                        _busy = true;\n                        try {\n                            pushEvent(\'leadoo\', \'\', null, null);\n                        } finally {\n                            _busy = false;\n                        }\n                    }\n                }\n            }\n            return _orig.apply(null, arguments);\n        };\n    }());\n\n    // ── 16. tel: and mailto: link clicks ──────────────────────\n    //\n    // Uses event delegation on document so dynamically injected links\n    // (popups, live chat widgets, etc.) are captured without re-binding.\n    // closest() walks up the DOM in case the click lands on a child\n    // element inside the anchor (e.g. an icon or span).\n    // hrefLower handles uppercase protocol variants (e.g. TEL:, MAILTO:).\n\n    document.addEventListener(\'click\', function (event) {\n        var anchor = event.target.closest(\'a[href]\');\n        if (!anchor) return;\n\n        var href = anchor.getAttribute(\'href\') || \'\';\n        var hrefLower = href.toLowerCase();\n        var linkText = anchor.textContent.trim();\n\n        if (hrefLower.indexOf(\'tel:\') === 0) {\n            pushLinkClick(\'wpseoai_tel_click\', \'tel\', href.slice(4), linkText);\n        } else if (hrefLower.indexOf(\'mailto:\') === 0) {\n            pushLinkClick(\'wpseoai_mail_click\', \'mailto\', href.slice(7), linkText);\n        }\n    }, false);\n\n})();\n\n//# sourceURL=seoaiwp-form-tracking-js-after\n</script>\n\n<script type=\"text/javascript\">window.NREUM||(NREUM={});NREUM.info={\"beacon\":\"bam.nr-data.net\",\"licenseKey\":\"e88816d150\",\"applicationID\":\"4617752\",\"transactionName\":\"YlNVbUACXkNVVUZfC1sZdlpGCl9eG0ZTUQEYUF5LX